export const DEFAULTS = {
  accounts: 40, visits: 4, serviceMinutes: 35, driveMinutes: 12,
  laborRate: 28, chemicalCost: 18, overhead: 12, targetMargin: 35
};

const number = (value, label) => {
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed < 0) throw new Error(`${label} must be zero or greater.`);
  return parsed;
};

/**
 * @param {number} [input.currentPrice] What you actually charge per account
 *   per month today. Optional — omit or leave blank to get only the minimum
 *   price. When given, the result includes `current`: your real margin and
 *   route profit at that price, so an operator checking an existing route
 *   (not just pricing a new one) can see the gap to the target, not just the
 *   floor.
 */
export function calculate(input) {
  const accounts = number(input.accounts, 'Accounts');
  const visits = number(input.visits, 'Visits per account');
  const serviceMinutes = number(input.serviceMinutes, 'Service minutes');
  const driveMinutes = number(input.driveMinutes, 'Drive minutes');
  const laborRate = number(input.laborRate, 'Labor rate');
  const chemicalCost = number(input.chemicalCost, 'Chemical cost');
  const overhead = number(input.overhead, 'Overhead per account');
  const targetMargin = number(input.targetMargin, 'Target margin');
  if (targetMargin >= 100) throw new Error('Target margin must be below 100%.');
  const monthlyHours = accounts * visits * (serviceMinutes + driveMinutes) / 60;
  const labor = monthlyHours * laborRate;
  const variableCost = accounts * visits * chemicalCost;
  const overheadCost = accounts * overhead;
  const totalCost = labor + variableCost + overheadCost;
  const minimumRouteRevenue = totalCost / (1 - targetMargin / 100);
  const minimumMonthlyPrice = accounts ? minimumRouteRevenue / accounts : 0;

  const hasCurrentPrice =
    input.currentPrice !== null && input.currentPrice !== undefined && input.currentPrice !== '';
  const currentPrice = hasCurrentPrice ? number(input.currentPrice, 'Price you currently charge') : null;

  // What an existing route actually clears today, priced the same way as
  // the minimum above — a share of route revenue, not a markup on cost —
  // so "am I hitting my target margin?" and "what's the floor?" answer
  // from the same arithmetic instead of two different formulas.
  const current = currentPrice === null ? null : (() => {
    const routeRevenue = currentPrice * accounts;
    const profit = routeRevenue - totalCost;
    const margin = routeRevenue === 0 ? 0 : (profit / routeRevenue) * 100;
    return {
      price: currentPrice,
      routeRevenue,
      profit,
      margin,
      meetsTarget: margin >= targetMargin - 1e-9,
      belowBreakEven: profit < 0,
      gapToMinimum: minimumMonthlyPrice - currentPrice,
    };
  })();

  return {
    accounts, visits, monthlyHours, labor, variableCost, overheadCost, totalCost,
    minimumRouteRevenue, minimumMonthlyPrice, targetMargin, current,
  };
}

share.mjs.text:
// A route operator's account count, service/drive minutes, labor rate,
// chemical cost, overhead, and target margin are what they re-enter every
// time they price a new route or revisit this one. Persisting them locally
// and letting them ride in a shareable link is what turns a one-off
// calculation into a tool worth returning to, and lets an operator send a
// route to a partner or franchise co-owner without re-typing eight numbers.
//
// This module is pure — no DOM, no storage, no network — so it is testable
// in `node --test` and reusable for both the localStorage draft and the
// shareable link, which serialize the same field set. Unknown keys never
// survive encode or decode, so a crafted or stale link can only ever set a
// known, non-negative numeric field.

import { DEFAULTS } from './calc.mjs';

// The eight route-assumption fields are always present, so they live in
// DEFAULTS and get a starting value on first load. `currentPrice` is a
// ninth, optional field — what an operator actually charges today, entered
// only when they're checking an existing route rather than pricing a new
// one — so it stays out of DEFAULTS (no default value to pin the field to)
// but still rides in the same draft/share round trip when it's been set.
export const FIELD_IDS = [...Object.keys(DEFAULTS), 'currentPrice'];

function usableNumber(value) {
  if (value === '' || value === null || value === undefined) return null;
  const result = Number(value);
  if (!Number.isFinite(result) || result < 0) return null;
  return result;
}

// inputs object -> query string (no leading '?'). Only known, valid,
// non-negative numbers are written; a blank or invalid field is left out so
// a partial link states nothing about it rather than pinning it to zero.
export function encodeInputs(inputs) {
  const params = new URLSearchParams();
  for (const id of FIELD_IDS) {
    const value = usableNumber(inputs?.[id]);
    if (value !== null) params.set(id, String(value));
  }
  return params.toString();
}

// query string -> inputs object. Accepts a bare query string, or one with a
// leading '?' or '#', so the caller can hand it `location.hash` or
// `location.search` without trimming first. A hostile or corrupted link
// yields only the fields that parse, so the page still works and just falls
// back to its own defaults for the rest.
export function decodeInputs(source) {
  if (typeof source !== 'string') return {};
  const trimmed = source.replace(/^[?#]/, '');
  const params = new URLSearchParams(trimmed);
  const inputs = {};
  for (const id of FIELD_IDS) {
    if (!params.has(id)) continue;
    const value = usableNumber(params.get(id));
    if (value !== null) inputs[id] = value;
  }
  return inputs;
}

// Drop query/hash from the current page URL, then attach the encoded route.
// The hash never leaves the recipient's browser; there is no server hop.
export function buildShareUrl(baseUrl, inputs) {
  const query = encodeInputs(inputs);
  const base = String(baseUrl || '').split('#')[0].split('?')[0];
  return query ? `${base}#${query}` : base;
}

usage.mjs.text:
const KEY = 'pool-route-pricing-usage';
const OPT_OUT = 'pool-route-pricing-usage-opt-out';

function storage() {
  try {
    return typeof localStorage !== 'undefined' ? localStorage : null;
  } catch {
    return null;
  }
}

export function usageAllowed() {
  if (typeof navigator !== 'undefined' && (navigator.doNotTrack === '1' || navigator.globalPrivacyControl)) {
    return false;
  }
  const ls = storage();
  if (!ls) return false;
  return ls.getItem(OPT_OUT) !== 'true';
}

export function recordEvent(event = 'estimate') {
  if (!usageAllowed()) return;
  try {
    const ls = storage();
    if (!ls) return;
    const counts = JSON.parse(ls.getItem(KEY) || '{}');
    counts[event] = (counts[event] || 0) + 1;
    ls.setItem(KEY, JSON.stringify(counts));
  } catch { /* Private browsing must not break the calculator. */ }
}

export function toggleUsage(enabled) {
  try {
    const ls = storage();
    if (!ls) return;
    ls.setItem(OPT_OUT, enabled ? 'false' : 'true');
  } catch { /* optional measurement */ }
}
